            print(i, ts, 'USER-TEXT', content[:200].replace(chr(10),' '))
        elif isinstance(content, list):
            for c in content:
                if c.get('type') == 'text':
                    print(i, ts, 'USER-TEXT', c['text'][:200].replace(chr(10),' '))
                elif c.get('type') == 'tool_result':
                    cc = c.get('content')
                    if isinstance(cc, list):
                        s = ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                    else:
                        s = str(cc)
                    print(i, ts, 'TOOL_RESULT', str(s)[:150].replace(chr(10),' '))
    elif t == 'assistant':
        msg = d.get('message', {})
        content = msg.get('content')
        if isinstance(content, list):
            for c in content:
                if c.get('type') == 'text':
                    print(i, ts, 'ASSISTANT-TEXT', c['text'][:200].replace(chr(10),' '))
                elif c.get('type') == 'tool_use':
                    print(i, ts, 'TOOL_USE', c.get('name'), str(c.get('input'))[:150].replace(chr(10),' '))
" > summary.txt
wc -l summary.txt

